import{_ as l}from"./chunks/sih_overview.DyJ331z2.js";import{_ as o,C as r,o as d,c as h,j as a,a as s,E as t,al as n}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"SIH Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"en/sim_sih/index.md","filePath":"en/sim_sih/index.md"}'),p={name:"en/sim_sih/index.md"},c={tabindex:"0"};function u(m,e,k,g,f,S){const i=r("Badge");return d(),h("div",null,[e[19]||(e[19]=a("h1",{id:"sih-simulation",tabindex:"-1"},[s("SIH Simulation "),a("a",{class:"header-anchor",href:"#sih-simulation","aria-label":'Permalink to "SIH Simulation"'},"​")],-1)),t(i,{type:"tip",text:"PX4 v1.9 (MC)"}),t(i,{type:"tip",text:"PX4 v1.13 (MC, VTOL, FW)"}),e[20]||(e[20]=s()),t(i,{type:"tip",text:"PX4 v1.16 (Rover)"}),e[21]||(e[21]=n('<p>SIH (Simulation-In-Hardware) is a lightweight, headless simulator with zero external dependencies that runs physics directly inside PX4 via uORB messages. No GUI, no external processes, no rendering overhead — just PX4 running a C++ physics model. This makes it the fastest way to iterate on flight code.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>SIH is also available as a <a href="./../simulation/px4_sitl_prebuilt_packages">prebuilt Docker container or .deb package</a>, which is useful if you don&#39;t need to modify PX4 itself. See <a href="./../simulation/px4_simulation_quickstart">PX4 Simulation QuickStart</a> for a one-line instruction on how this is used.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>SIH runs as a PX4 module that replaces real sensor and actuator hardware with a simulated physics model. It provides simulated IMU, GPS, barometer, magnetometer, and airspeed sensor data via uORB, and reads actuator outputs to update the vehicle state at each timestep.</p><p>The simulation runs in lockstep with PX4, ensuring deterministic and reproducible results. It also integrates seamlessly with ROS 2 with no additional configuration (see <a href="#ros-2-integration">ROS 2 Integration</a> below).</p><p>Two modes are supported:</p><ul><li><p><strong><a href="#sih-as-sitl-no-fc">SITL</a>:</strong> Runs on your computer with no hardware needed, and headless (without a UI) by default. <em>This is the fastest and easiest way to start a simulation on PX4.</em></p></li><li><p><strong><a href="#sih-on-flight-controller-hardware">SIH on flight controller hardware</a>:</strong> Runs the entire simulation on the autopilot (<code>SYS_HITL=2</code>).</p></li></ul><h3 id="supported-vehicle-types" tabindex="-1">Supported Vehicle Types <a class="header-anchor" href="#supported-vehicle-types" aria-label="Permalink to &quot;Supported Vehicle Types&quot;">​</a></h3><p>The following vehicle types are supported:</p>',9)),a("table",c,[e[18]||(e[18]=a("thead",null,[a("tr",null,[a("th",null,"Vehicle"),a("th",null,"Make Target"),a("th",null,"Status")])],-1)),a("tbody",null,[a("tr",null,[a("td",null,[e[0]||(e[0]=s("Quadrotor X ",-1)),t(i,{type:"tip",text:"PX4 v1.9"})]),e[1]||(e[1]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_quadx")],-1)),e[2]||(e[2]=a("td",null,"Stable",-1))]),a("tr",null,[a("td",null,[e[3]||(e[3]=s("Hexarotor X ",-1)),t(i,{type:"tip",text:"PX4 v1.16"})]),e[4]||(e[4]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_hex")],-1)),e[5]||(e[5]=a("td",null,"Experimental",-1))]),a("tr",null,[a("td",null,[e[6]||(e[6]=s("Fixed-wing (airplane) ",-1)),t(i,{type:"tip",text:"PX4 v1.13"})]),e[7]||(e[7]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_airplane")],-1)),e[8]||(e[8]=a("td",null,"Experimental",-1))]),a("tr",null,[a("td",null,[e[9]||(e[9]=s("Tailsitter VTOL ",-1)),t(i,{type:"tip",text:"PX4 v1.13"})]),e[10]||(e[10]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_xvert")],-1)),e[11]||(e[11]=a("td",null,"Experimental",-1))]),a("tr",null,[a("td",null,[e[12]||(e[12]=s("Standard VTOL (QuadPlane) ",-1)),t(i,{type:"tip",text:"PX4 v1.16"})]),e[13]||(e[13]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_standard_vtol")],-1)),e[14]||(e[14]=a("td",null,"Experimental",-1))]),a("tr",null,[a("td",null,[e[15]||(e[15]=s("Ackermann Rover ",-1)),t(i,{type:"tip",text:"PX4 v1.16"})]),e[16]||(e[16]=a("td",null,[a("code",null,"make px4_sitl_sih sihsim_rover_ackermann")],-1)),e[17]||(e[17]=a("td",null,"Experimental",-1))])])]),e[22]||(e[22]=n('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only the quadrotor vehicle type is stable and recommended for development. All other vehicle types (hexarotor, fixed-wing, VTOL, rover) are experimental and may have aerodynamic model or controller interaction issues that produce unrealistic flight behaviour.</p></div><h3 id="how-sih-works" tabindex="-1">How SIH Works <a class="header-anchor" href="#how-sih-works" aria-label="Permalink to &quot;How SIH Works&quot;">​</a></h3><p><img src="'+l+`" alt="SIH Overview"></p><p>SIH differs from external simulators:</p><ul><li><strong>No MAVLink simulator API:</strong> SIH communicates entirely via uORB (PX4&#39;s internal message bus).</li><li><strong>No external process:</strong> The physics model runs in the same PX4 process.</li><li><strong>Lockstep by default:</strong> Simulation time is synchronized with PX4 scheduling.</li></ul><h2 id="sih-as-sitl-no-fc" tabindex="-1">SIH as SITL <a class="header-anchor" href="#sih-as-sitl-no-fc" aria-label="Permalink to &quot;SIH as SITL {#sih-as-sitl-no-fc}&quot;">​</a></h2><p>SIH as SITL is the easiest and fastest way to set up a simulator with PX4. It requires no hardware, and very few extra dependencies.</p><h3 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h3><p>To build PX4 and run SIH for a quadrotor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div><p>QGroundControl auto-connects on UDP port 14550 — just open it and you&#39;ll see the vehicle. Note that the simulation is &quot;headless&quot; by default (has no GUI), but you can use an external viewer.</p><p>See <a href="#supported-vehicle-types">Supported vehicle types</a> for other vehicles.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <code>px4_sitl_sih</code> build target! The <code>px4_sitl</code> target will work, but will also build Gazebo libraries.</p></div><h3 id="sitl-visualization" tabindex="-1">Visualization (Optional) <a class="header-anchor" href="#sitl-visualization" aria-label="Permalink to &quot;Visualization (Optional) {#sitl-visualization}&quot;">​</a></h3><p>SIH is intentionally headless by default. If you need a visual aid to see what the vehicle is doing you can use QGroundControl to track path over ground, and/or <a href="./../sim_hawkeye/">Hawkeye</a> as a 3D viewer.</p><h4 id="qgroundcontrol" tabindex="-1">QGroundControl <a class="header-anchor" href="#qgroundcontrol" aria-label="Permalink to &quot;QGroundControl&quot;">​</a></h4><p>QGC auto-connects on UDP port 14550. Open QGC while SIH is running and the vehicle appears on the map view with attitude, position, and telemetry.</p><h4 id="hawkeye-3d-visualizer" tabindex="-1">Hawkeye (3D Visualizer) <a class="header-anchor" href="#hawkeye-3d-visualizer" aria-label="Permalink to &quot;Hawkeye (3D Visualizer)&quot;">​</a></h4><p><a href="./../sim_hawkeye/">Hawkeye</a> renders a real-time 3D view of the vehicle using MAVLink position data. No physics are simulated in Hawkeye — it is a visualizer only.</p><p>In a separate terminal, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hawkeye</span></span></code></pre></div><p>Hawkeye connects on UDP port 19410 by default (the same port SIH sends <code>HIL_STATE_QUATERNION</code> on). It then auto-detects the vehicle type from the MAVLink <code>HEARTBEAT</code> and loads the matching 3D model.</p><p>The <a href="./../sim_hawkeye/">Hawkeye</a> overview page explains how to install the software. See the <a href="https://px4.github.io/Hawkeye/" target="_blank" rel="noreferrer">Hawkeye docs</a> for other features, such as ULog replay, and multi-vehicle visualization.</p><h3 id="environment-configuration" tabindex="-1">Environment Configuration <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;Environment Configuration&quot;">​</a></h3><h4 id="change-simulation-speed" tabindex="-1">Change Simulation Speed <a class="header-anchor" href="#change-simulation-speed" aria-label="Permalink to &quot;Change Simulation Speed&quot;">​</a></h4><p>SIH supports faster-than-realtime simulation via the <code>PX4_SIM_SPEED_FACTOR</code> environment variable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run at 10x speed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SIM_SPEED_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div><h4 id="wind-simulation" tabindex="-1">Wind Simulation <a class="header-anchor" href="#wind-simulation" aria-label="Permalink to &quot;Wind Simulation&quot;">​</a></h4><p>SIH supports setting a wind velocity with the PX4 parameters <a href="./../advanced_config/parameter_reference#SIH_WIND_E"><code>SIH_WIND_N</code></a> and <a href="./../advanced_config/parameter_reference#SIH_WIND_E"><code>SIH_WIND_E</code></a> [m/s]. The parameters can also be changed during flight to simulate changing wind.</p><h4 id="set-custom-takeoff-location" tabindex="-1">Set Custom Takeoff Location <a class="header-anchor" href="#set-custom-takeoff-location" aria-label="Permalink to &quot;Set Custom Takeoff Location&quot;">​</a></h4><p>The default takeoff location can be set using environment variables:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_LAT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">28.452386</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_LON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-13.867138</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_ALT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">28.5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div><h3 id="ros-2-integration" tabindex="-1">ROS 2 Integration <a class="header-anchor" href="#ros-2-integration" aria-label="Permalink to &quot;ROS 2 Integration&quot;">​</a></h3><p>SIH works with ROS 2 via the <a href="./../middleware/uxrce_dds">uXRCE-DDS</a> client, which auto-starts in SITL mode. This is the same mechanism used by Gazebo — both simulators expose the same set of uORB topics to ROS 2. The DDS agent connects on UDP port <strong>8888</strong> by default (configurable via <code>UXRCE_DDS_PRT</code> parameter or <code>PX4_UXRCE_DDS_PORT</code> environment variable).</p><p>To use SIH with ROS 2:</p><ol><li><p>Start SIH:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div></li><li><p>In a separate terminal, start the Micro XRCE-DDS Agent:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MicroXRCEAgent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udp4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span></code></pre></div></li></ol><p>See <a href="./../middleware/uxrce_dds">uXRCE-DDS (PX4-ROS 2/DDS Bridge)</a> for full setup instructions, including agent installation and ROS 2 workspace configuration.</p><h3 id="port-reference" tabindex="-1">Port Reference <a class="header-anchor" href="#port-reference" aria-label="Permalink to &quot;Port Reference&quot;">​</a></h3><p>PX4 SITL opens the following UDP ports (all instance-aware, offset by instance number N).</p><table tabindex="0"><thead><tr><th>PX4 sends to (remote)</th><th>PX4 listens on (local)</th><th>Use for</th><th>Instance offset</th></tr></thead><tbody><tr><td><strong>14550</strong></td><td>18570 (+N)</td><td>QGroundControl, GCS tools</td><td>Yes</td></tr><tr><td><strong>14540</strong> (+N)</td><td>14580 (+N)</td><td>MAVSDK, MAVROS, offboard APIs</td><td>Yes (capped at 14549 for 10+ instances)</td></tr><tr><td><strong>14030</strong> (+N)</td><td>14280 (+N)</td><td>Onboard camera/payload</td><td>Yes</td></tr><tr><td><strong>13280</strong> (+N)</td><td>13030 (+N)</td><td>Gimbal control</td><td>Yes</td></tr><tr><td><strong>19410</strong> (+N)</td><td>19450 (+N)</td><td>Hawkeye visualizer (SIH only)</td><td>Yes</td></tr><tr><td><strong>8888</strong></td><td>-</td><td>uXRCE-DDS / ROS 2</td><td>No (use DDS namespace for multi-instance)</td></tr></tbody></table><p>QGC auto-connects on port <strong>14550</strong> by default. MAVSDK connects on <strong>14540</strong>. No manual port configuration needed for single-instance use.</p><h3 id="multi-vehicle-simulation" tabindex="-1">Multi-Vehicle Simulation <a class="header-anchor" href="#multi-vehicle-simulation" aria-label="Permalink to &quot;Multi-Vehicle Simulation&quot;">​</a></h3><p>SIH supports multi-vehicle simulation using PX4&#39;s instance system. Each instance gets unique MAVLink ports, a unique system ID, and a separate DDS namespace.</p><p>To launch multiple SIH vehicles, first build:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div><p>Then use the multi-instance launch script:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/simulation/sitl_multiple_run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span></span></code></pre></div><p>Or launch instances manually:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1 (instance 0)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2 (instance 1)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/px4_sitl_sih/bin/px4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build/px4_sitl_sih/etc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 3 (instance 2)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/px4_sitl_sih/bin/px4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build/px4_sitl_sih/etc</span></span></code></pre></div><p>Each instance allocates ports automatically (all offset by instance number):</p><table tabindex="0"><thead><tr><th>Instance</th><th>MAVLink (18570+N)</th><th>MAVLink (14540+N)</th><th>DDS (8888) Namespace</th></tr></thead><tbody><tr><td>0</td><td>18570</td><td>14540</td><td>(default)</td></tr><tr><td>1</td><td>18571</td><td>14541</td><td>px4_1</td></tr><tr><td>2</td><td>18572</td><td>14542</td><td>px4_2</td></tr></tbody></table><p>See <a href="#port-reference">Port Reference</a> for the complete list of ports.</p><h2 id="sih-on-flight-controller-hardware" tabindex="-1">Running the SIH on Flight Controller Hardware <a class="header-anchor" href="#sih-on-flight-controller-hardware" aria-label="Permalink to &quot;Running the SIH on Flight Controller Hardware {#sih-on-flight-controller-hardware}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The SIH on flight controller is community supported.</p></div><p>SIH can also run on flight controller hardware, replacing real sensors with simulated data while running on the actual autopilot. See <a href="./hardware">SIH on Flight Controller Hardware</a> for setup instructions.</p><h2 id="adding-new-airframes" tabindex="-1">Adding New Airframes <a class="header-anchor" href="#adding-new-airframes" aria-label="Permalink to &quot;Adding New Airframes&quot;">​</a></h2><p><a href="./../dev_airframes/adding_a_new_frame">Adding a new airframe</a> for use in SIH simulation is much the same as for other use cases. You still need to configure your vehicle type and <a href="./../config/actuators">geometry</a> (<code>CA_</code> parameters) and start any other defaults for that specific vehicle.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Not every vehicle can be simulated with SIH — there are currently <a href="./../advanced_config/parameter_reference#SIH_VEHICLE_TYPE">six supported vehicle types</a> (quadcopter, fixed-wing, tailsitter, standard VTOL, hexacopter, rover), each of which has a relatively rigid implementation in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/simulation/simulator_sih/sih.cpp" target="_blank" rel="noreferrer"><code>sih.cpp</code></a>.</p></div><p>The specific differences for SIH simulation airframes are listed in the sections below.</p><h3 id="all-variants" tabindex="-1">All Variants <a class="header-anchor" href="#all-variants" aria-label="Permalink to &quot;All Variants&quot;">​</a></h3><ul><li><p>Set all the <a href="./../advanced_config/parameter_reference#simulation-in-hardware">Simulation In Hardware</a> parameters (prefixed with <code>SIH_</code>) in order to configure the physical model of the vehicle.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make sure that the <code>SIH_*</code> parameters and the <code>CA_*</code> parameters describe the same vehicle. Note that some of these parameters are redundant!</p></div></li><li><p><code>param set-default SYS_HITL 2</code> to enable SIH on the next boot.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This also disables input from real sensors. For SIH on the FC (only), it also enables the simulated GPS, barometer, magnetometer, and airspeed sensor.</p><p>For SIH on SITL you will need to explicitly enable these sensors as shown below.</p></div></li><li><p><code>param set-default SENS_GPS0_DELAY 0</code> to improve state estimator performance (the assumption of instant GPS measurements would normally be unrealistic, but is accurate for SIH).</p></li></ul><h3 id="sih-on-flight-controller" tabindex="-1">SIH on Flight Controller <a class="header-anchor" href="#sih-on-flight-controller" aria-label="Permalink to &quot;SIH on Flight Controller&quot;">​</a></h3><p>See <a href="./../sim_sih/hardware#adding-new-airframes-fc">Adding New Airframes (FC)</a> in <em>SIH on Flight Controller Hardware</em>.</p><h3 id="sih-as-sitl" tabindex="-1">SIH as SITL <a class="header-anchor" href="#sih-as-sitl" aria-label="Permalink to &quot;SIH as SITL&quot;">​</a></h3><ul><li>Airframe file goes in <code>ROMFS/px4fmu_common/init.d-posix/airframes</code> and follows the naming template <code>\${ID}_sihsim_\${model_name}</code>, where <code>ID</code> is the <code>SYS_AUTOSTART_ID</code> used to select the airframe, and <code>model_name</code> is the airframe model name.</li><li>Add the model name in <code>src/modules/simulation/simulator_sih/CMakeLists.txt</code> to generate a corresponding make target.</li><li>Actuators are configured as usual with <code>PWM_MAIN_FUNC*</code> and <code>PWM_MAIN_REV</code>.</li><li>Additionally, set: <ul><li><code>PX4_SIMULATOR=\${PX4_SIMULATOR:=sihsim}</code></li><li><code>PX4_SIM_MODEL=\${PX4_SIM_MODEL:=svtol}</code> (replacing <code>svtol</code> with the airframe model name)</li></ul></li><li>Enable the simulated sensors using <a href="./../advanced_config/parameter_reference#SENS_EN_GPSSIM">SENS_EN_GPSSIM</a>, <a href="./../advanced_config/parameter_reference#SENS_EN_BAROSIM">SENS_EN_BAROSIM</a>, <a href="./../advanced_config/parameter_reference#SENS_EN_MAGSIM">SENS_EN_MAGSIM</a>, and <a href="./../advanced_config/parameter_reference#SENS_EN_ARSPDSIM">SENS_EN_ARSPDSIM</a> (this is only needed for SIH-as-SITL): <ul><li><code>param set-default SENS_EN_GPSSIM 1</code></li><li><code>param set-default SENS_EN_BAROSIM 1</code></li><li><code>param set-default SENS_EN_MAGSIM 1</code></li><li><code>param set-default SENS_EN_ARSPDSIM 1</code> (if it is a fixed-wing or VTOL airframe with airspeed sensor)</li></ul></li></ul><p>For specific examples see the <code>_sihsim_</code> airframes in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d-posix/airframes" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d-posix/airframes</a> (SIH as SITL) and <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d/airframes" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d/airframes</a> (SIH on FC).</p><h2 id="dynamic-models" tabindex="-1">Dynamic Models <a class="header-anchor" href="#dynamic-models" aria-label="Permalink to &quot;Dynamic Models&quot;">​</a></h2><p>The dynamic models for the various vehicles are:</p><ul><li>Quadrotor: <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/simulation/SIH_dynamic_model.pdf" target="_blank" rel="noreferrer">pdf</a></li><li>Fixed-wing: based on Khan (2016), see references below</li><li>Tailsitter: based on Chiappinelli (2018), see references below</li><li>Rover: bicycle model with linear tire model</li></ul><p><strong>Propeller model with advance ratio</strong></p><p>Since PX4 v1.17, the propeller model for fixed-wing, tailsitter, and VTOL pusher vehicles is based on the equations from UIUC Propeller Database.</p><img width="588" height="183" alt="UIUC_prop_equations" src="https://github.com/user-attachments/assets/55413486-b23b-4269-9ac5-dd630ec0849b"><p>This model includes the thrust coefficient CT(J) and power coefficient CP(J) as functions of the advance ratio J. As a result, the maximum thrust force is realistically reduced as the aircraft speed is increased. The SIH implements the thrust and power coefficients as second-order polynomial fits.</p><p>CT = SIH_F_CT0 + SIH_F_CT1⋅J + SIH_F_CT2⋅J²</p><p>CP = SIH_F_CP0 + SIH_F_CP1⋅J + SIH_F_CP2⋅J²</p><p>If <code>SIH_F_CT0</code> and <code>SIH_F_CP0</code> are non-zero and positive, the SIH uses the model with advance ratio. If not, the SIH uses a simple model with maximum thrust force given by <code>SIH_F_T_MAX</code> and maximum torque given by <code>SIH_F_Q_MAX</code>.</p><p><strong>References:</strong></p><ol><li>PX4 Development Team, &quot;SIH Dynamic Model,&quot; PX4-Autopilot, 2019. <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/simulation/SIH_dynamic_model.pdf" target="_blank" rel="noreferrer">PDF</a></li><li>W. Khan, &quot;Dynamics modeling of agile fixed-wing unmanned aerial vehicles,&quot; Ph.D. thesis, Dept. of Mechanical Engineering, McGill University, Montreal, 2016.</li><li>R. Chiappinelli, &quot;Modeling and control of a flying wing tailsitter unmanned aerial vehicle,&quot; M.Sc. thesis, Dept. of Mechanical Engineering, McGill University, Montreal, 2018.</li><li>S. Anumakonda, &quot;Everything you need to know about Self-Driving Cars,&quot; 2021. <a href="https://srianumakonda.medium.com/everything-you-need-to-know-about-self-driving-in-30-minutes-b38d68bd3427" target="_blank" rel="noreferrer">Link</a></li><li>J.B. Brandt, R.W. Deters, G.K. Ananda, O.D. Dantsker, and M.S. Selig, UIUC Propeller Database, Vols 1-4, University of Illinois at Urbana-Champaign, Department of Aerospace Engineering, retrieved from <a href="https://m-selig.ae.illinois.edu/props/propDB.html" target="_blank" rel="noreferrer">https://m-selig.ae.illinois.edu/props/propDB.html</a>.</li></ol><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2><p>SIH demo with a fixed-wing vehicle @<a href="https://youtu.be/PzIpSCRD8Jo" target="_blank" rel="noreferrer">youtube</a> How to parametrize the thrust and power coefficients CT &amp; CP @<a href="https://www.youtube.com/watch?v=KNSd9ge0sSw" target="_blank" rel="noreferrer">youtube</a></p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>SIH was originally developed by Coriolis g Corporation. The airplane model and tailsitter models were added by Altitude R&amp;D inc.</p><ul><li>Coriolis g developed a new type of Vertical Takeoff and Landing (VTOL) vehicles based on passive coupling systems;</li><li><a href="https://www.altitude-rd.com/" target="_blank" rel="noreferrer">Altitude R&amp;D</a> is specialized in dynamics, control, and real-time simulation (located in Zurich).</li></ul><p>The simulator is released for free under BSD license.</p>`,84))])}const v=o(p,[["render",u]]);export{y as __pageData,v as default};
